  if(!['change','inspect','clarify'].includes(plan.mode))throw new Error('Invalid plan mode');
  if(typeof plan.summary!=='string'||plan.summary.length>3000)throw new Error('A concise plan summary is required');
  if(!Array.isArray(plan.acceptance)||plan.acceptance.length>15||plan.acceptance.some(x=>typeof x!=='string'||x.length>600))throw new Error('Provide at most 15 acceptance criteria');
  if(plan.mode==='change'){
   safeBranch(plan.branch);
   const explicit=[...new Set((m.task.match(/feature\/[a-z0-9][a-z0-9._/-]*/g)||[]).map(x=>x.replace(/[.,/]$/,'')))];
   if(explicit.length===1&&plan.branch!==explicit[0])throw new Error('Use the branch explicitly named by the user');
   const branches=m.snapshot.branches.items||[];
   const evidenceBranch=m.snapshot.evidence?.source_branch;
